window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-77edd6ad2ce51cf0"]={"versions": [{"id": "FIG-77edd6ad2ce51cf0", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm / Instanzendiagramm im Kontext des AUTOSAR-Modell-Merges und der Werkzeug-Interoperabilität (AUTOSAR_TR_InteroperabilityOfAutosarTools). Das Diagramm illustriert das Ergebnis des Zusammenführens zweier partieller ARXML-Modelle auf Basis des AUTOSAR-Metamodells unter Berücksichtigung von Splitting-Regeln («atpSplitable») und Konflikterkennung bei nicht splittbaren Aggregationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>:Root: Oberstes Wurzelelement des fusionierten Modells.</li>\n<li>:Package (shortName = OEM1): Aggregiert über die mit «atpSplitable» stereotypisierte Komposition +package unter :Root.</li>\n<li>:Element1 (shortName = CentralLockingMaster): Instanz von Element1, aggregiert von :Package über +element («atpSplitable»); enthält eine Komposition +dataSpec («atpSplitable») auf eine Instanz :DataSpec mit dem Attributwert attribute1 = text1.</li>\n<li>:Element1 (shortName = PassengerDoorLock): Weitere Instanz von Element1 unter :Package über +element («atpSplitable»); enthält eine Komposition +dataSpec («atpSplitable») auf eine Instanz :DataSpec mit attribute1 = one text und attribute2 = onother text.</li>\n<li>:Element2 (uuid = 3, shortName = engineControl): Instanz von Element2 aus dem ersten Teilmodell, aggregiert über +element («atpSplitable») unter :Package.</li>\n<li>:Element2 (shortName = engineControl, shortLabel = TwoSpec): Instanz von Element2 aus dem zweiten Teilmodell; aggregiert eine Instanz :DataSpec (attribute1 = text 21, attribute2 = text 22) über die nicht splittbare Komposition +dataSpec.</li>\n<li>Kommentar-Notiz (rot hinterlegt): Referenziert über gestrichelte Verbindungslinien beide :Element2-Instanzen mit dem Text \"conflict. aggregation dataSpec on Element2 is not splitable.\".</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Dargestellt ist ein statischer Zustand nach einem Drei-Wege- bzw. Zwei-Wege-Merge:</p>\n<ol class=\"fig-list\">\n<li>Gleiche Elemente mit identischem Bezeichner (shortName = OEM1) werden in eine gemeinsame :Package-Instanz zusammengeführt.</li>\n<li>Unikate Elemente (:Element1 mit CentralLockingMaster bzw. PassengerDoorLock) verbleiben disjunkt nebeneinander im aggregierenden Paket.</li>\n<li>Elemente gleichen Namens (engineControl), deren Kind-Aggregation (+dataSpec) nicht mit «atpSplitable» ausgezeichnet ist, können bei divergierenden Attributen / Kindelementen nicht automatisch vereinigt werden; sie verbleiben getrennt und erzeugen einen Aggregationskonflikt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Werkzeuge für den AUTOSAR-Modellaustausch und -Merge müssen Stereotypen des Typs «atpSplitable» an Kompositionsrollen auswerten. Fehlt die Eigenschaft «atpSplitable» an einer Aggregation (wie bei Element2 -> dataSpec), dürfen Instanzen mit abweichenden Kindelementen nicht stillschweigend gemischt werden. Der modellierte Zustand zeigt den resultierenden Konfliktfall, der eine manuelle Auflösung oder einen Abbruch des Werkzeug-Merges erfordert.</p>"}, {"id": "FIG-c9480319b545cd6f", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm / Instanzendiagramm im Kontext des AUTOSAR-Modell-Merges und der Werkzeug-Interoperabilität (AUTOSAR_TR_InteroperabilityOfAutosarTools). Das Diagramm illustriert das Ergebnis des Zusammenführens zweier partieller ARXML-Modelle auf Basis des AUTOSAR-Metamodells unter Berücksichtigung von Splitting-Regeln («atpSplitable») und Konflikterkennung bei nicht splittbaren Aggregationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>:Root: Oberstes Wurzelelement des fusionierten Modells.</li>\n<li>:Package (shortName = OEM1): Aggregiert über die mit «atpSplitable» stereotypisierte Komposition +package unter :Root.</li>\n<li>:Element1 (shortName = CentralLockingMaster): Instanz von Element1, aggregiert von :Package über +element («atpSplitable»); enthält eine Komposition +dataSpec («atpSplitable») auf eine Instanz :DataSpec mit dem Attributwert attribute1 = text1.</li>\n<li>:Element1 (shortName = PassengerDoorLock): Weitere Instanz von Element1 unter :Package über +element («atpSplitable»); enthält eine Komposition +dataSpec («atpSplitable») auf eine Instanz :DataSpec mit attribute1 = one text und attribute2 = onother text.</li>\n<li>:Element2 (uuid = 3, shortName = engineControl): Instanz von Element2 aus dem ersten Teilmodell, aggregiert über +element («atpSplitable») unter :Package.</li>\n<li>:Element2 (shortName = engineControl, shortLabel = TwoSpec): Instanz von Element2 aus dem zweiten Teilmodell; aggregiert eine Instanz :DataSpec (attribute1 = text 21, attribute2 = text 22) über die nicht splittbare Komposition +dataSpec.</li>\n<li>Kommentar-Notiz (rot hinterlegt): Referenziert über gestrichelte Verbindungslinien beide :Element2-Instanzen mit dem Text \"conflict. aggregation dataSpec on Element2 is not splitable.\".</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Dargestellt ist ein statischer Zustand nach einem Drei-Wege- bzw. Zwei-Wege-Merge:</p>\n<ol class=\"fig-list\">\n<li>Gleiche Elemente mit identischem Bezeichner (shortName = OEM1) werden in eine gemeinsame :Package-Instanz zusammengeführt.</li>\n<li>Unikate Elemente (:Element1 mit CentralLockingMaster bzw. PassengerDoorLock) verbleiben disjunkt nebeneinander im aggregierenden Paket.</li>\n<li>Elemente gleichen Namens (engineControl), deren Kind-Aggregation (+dataSpec) nicht mit «atpSplitable» ausgezeichnet ist, können bei divergierenden Attributen / Kindelementen nicht automatisch vereinigt werden; sie verbleiben getrennt und erzeugen einen Aggregationskonflikt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Werkzeuge für den AUTOSAR-Modellaustausch und -Merge müssen Stereotypen des Typs «atpSplitable» an Kompositionsrollen auswerten. Fehlt die Eigenschaft «atpSplitable» an einer Aggregation (wie bei Element2 -> dataSpec), dürfen Instanzen mit abweichenden Kindelementen nicht stillschweigend gemischt werden. Der modellierte Zustand zeigt den resultierenden Konfliktfall, der eine manuelle Auflösung oder einen Abbruch des Werkzeug-Merges erfordert.</p>"}, {"id": "FIG-0f8e6e93fc3a415f", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm / Instanzendiagramm im Kontext des AUTOSAR-Modell-Merges und der Werkzeug-Interoperabilität (AUTOSAR_TR_InteroperabilityOfAutosarTools). Das Diagramm illustriert das Ergebnis des Zusammenführens zweier partieller ARXML-Modelle auf Basis des AUTOSAR-Metamodells unter Berücksichtigung von Splitting-Regeln («atpSplitable») und Konflikterkennung bei nicht splittbaren Aggregationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>:Root: Oberstes Wurzelelement des fusionierten Modells.</li>\n<li>:Package (shortName = OEM1): Aggregiert über die mit «atpSplitable» stereotypisierte Komposition +package unter :Root.</li>\n<li>:Element1 (shortName = CentralLockingMaster): Instanz von Element1, aggregiert von :Package über +element («atpSplitable»); enthält eine Komposition +dataSpec («atpSplitable») auf eine Instanz :DataSpec mit dem Attributwert attribute1 = text1.</li>\n<li>:Element1 (shortName = PassengerDoorLock): Weitere Instanz von Element1 unter :Package über +element («atpSplitable»); enthält eine Komposition +dataSpec («atpSplitable») auf eine Instanz :DataSpec mit attribute1 = one text und attribute2 = onother text.</li>\n<li>:Element2 (uuid = 3, shortName = engineControl): Instanz von Element2 aus dem ersten Teilmodell, aggregiert über +element («atpSplitable») unter :Package.</li>\n<li>:Element2 (shortName = engineControl, shortLabel = TwoSpec): Instanz von Element2 aus dem zweiten Teilmodell; aggregiert eine Instanz :DataSpec (attribute1 = text 21, attribute2 = text 22) über die nicht splittbare Komposition +dataSpec.</li>\n<li>Kommentar-Notiz (rot hinterlegt): Referenziert über gestrichelte Verbindungslinien beide :Element2-Instanzen mit dem Text \"conflict. aggregation dataSpec on Element2 is not splitable.\".</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Dargestellt ist ein statischer Zustand nach einem Drei-Wege- bzw. Zwei-Wege-Merge:</p>\n<ol class=\"fig-list\">\n<li>Gleiche Elemente mit identischem Bezeichner (shortName = OEM1) werden in eine gemeinsame :Package-Instanz zusammengeführt.</li>\n<li>Unikate Elemente (:Element1 mit CentralLockingMaster bzw. PassengerDoorLock) verbleiben disjunkt nebeneinander im aggregierenden Paket.</li>\n<li>Elemente gleichen Namens (engineControl), deren Kind-Aggregation (+dataSpec) nicht mit «atpSplitable» ausgezeichnet ist, können bei divergierenden Attributen / Kindelementen nicht automatisch vereinigt werden; sie verbleiben getrennt und erzeugen einen Aggregationskonflikt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Werkzeuge für den AUTOSAR-Modellaustausch und -Merge müssen Stereotypen des Typs «atpSplitable» an Kompositionsrollen auswerten. Fehlt die Eigenschaft «atpSplitable» an einer Aggregation (wie bei Element2 -> dataSpec), dürfen Instanzen mit abweichenden Kindelementen nicht stillschweigend gemischt werden. Der modellierte Zustand zeigt den resultierenden Konfliktfall, der eine manuelle Auflösung oder einen Abbruch des Werkzeug-Merges erfordert.</p>"}, {"id": "FIG-2f5a03b9f66a950f", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm / Instanzendiagramm im Kontext des AUTOSAR-Modell-Merges und der Werkzeug-Interoperabilität (AUTOSAR_TR_InteroperabilityOfAutosarTools). Das Diagramm illustriert das Ergebnis des Zusammenführens zweier partieller ARXML-Modelle auf Basis des AUTOSAR-Metamodells unter Berücksichtigung von Splitting-Regeln («atpSplitable») und Konflikterkennung bei nicht splittbaren Aggregationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>:Root: Oberstes Wurzelelement des fusionierten Modells.</li>\n<li>:Package (shortName = OEM1): Aggregiert über die mit «atpSplitable» stereotypisierte Komposition +package unter :Root.</li>\n<li>:Element1 (shortName = CentralLockingMaster): Instanz von Element1, aggregiert von :Package über +element («atpSplitable»); enthält eine Komposition +dataSpec («atpSplitable») auf eine Instanz :DataSpec mit dem Attributwert attribute1 = text1.</li>\n<li>:Element1 (shortName = PassengerDoorLock): Weitere Instanz von Element1 unter :Package über +element («atpSplitable»); enthält eine Komposition +dataSpec («atpSplitable») auf eine Instanz :DataSpec mit attribute1 = one text und attribute2 = onother text.</li>\n<li>:Element2 (uuid = 3, shortName = engineControl): Instanz von Element2 aus dem ersten Teilmodell, aggregiert über +element («atpSplitable») unter :Package.</li>\n<li>:Element2 (shortName = engineControl, shortLabel = TwoSpec): Instanz von Element2 aus dem zweiten Teilmodell; aggregiert eine Instanz :DataSpec (attribute1 = text 21, attribute2 = text 22) über die nicht splittbare Komposition +dataSpec.</li>\n<li>Kommentar-Notiz (rot hinterlegt): Referenziert über gestrichelte Verbindungslinien beide :Element2-Instanzen mit dem Text \"conflict. aggregation dataSpec on Element2 is not splitable.\".</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Dargestellt ist ein statischer Zustand nach einem Drei-Wege- bzw. Zwei-Wege-Merge:</p>\n<ol class=\"fig-list\">\n<li>Gleiche Elemente mit identischem Bezeichner (shortName = OEM1) werden in eine gemeinsame :Package-Instanz zusammengeführt.</li>\n<li>Unikate Elemente (:Element1 mit CentralLockingMaster bzw. PassengerDoorLock) verbleiben disjunkt nebeneinander im aggregierenden Paket.</li>\n<li>Elemente gleichen Namens (engineControl), deren Kind-Aggregation (+dataSpec) nicht mit «atpSplitable» ausgezeichnet ist, können bei divergierenden Attributen / Kindelementen nicht automatisch vereinigt werden; sie verbleiben getrennt und erzeugen einen Aggregationskonflikt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Werkzeuge für den AUTOSAR-Modellaustausch und -Merge müssen Stereotypen des Typs «atpSplitable» an Kompositionsrollen auswerten. Fehlt die Eigenschaft «atpSplitable» an einer Aggregation (wie bei Element2 -> dataSpec), dürfen Instanzen mit abweichenden Kindelementen nicht stillschweigend gemischt werden. Der modellierte Zustand zeigt den resultierenden Konfliktfall, der eine manuelle Auflösung oder einen Abbruch des Werkzeug-Merges erfordert.</p>"}], "trans": [{"from": "FIG-77edd6ad2ce51cf0", "to": "FIG-c9480319b545cd6f", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>:Package, :Element1, :Element2, :DataSpec: UML-Objektboxen wurden mit Trennlinie zwischen Klassenbezeichnerkopf und Attributfach neu gerendert.</li>\n</ul>"}, {"from": "FIG-c9480319b545cd6f", "to": "FIG-0f8e6e93fc3a415f", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0f8e6e93fc3a415f", "to": "FIG-2f5a03b9f66a950f", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
